    '센서 무선 통신 거리는 얼마나 되나요?': 'What is the wireless communication range?',
    '대부분의 ALTA 센서는 전원을 켜는 즉시 게이트웨이에 연결되는 플러그앤플레이 방식으로, 시스템 구성에 보통 15분이면 충분합니다. Monnit Korea가 현장 설치와 초기 설정을 지원합니다.':
      'Most ALTA sensors are plug-and-play and connect to the gateway as soon as they power on, so setup typically takes about 15 minutes. Monnit Korea supports on-site installation and initial configuration.',
    '사용 환경에 따라 다르지만, 단일 AA 배터리로 최대 10년 이상 사용 가능합니다. 데이터 전송 주기(하트비트), 통신 거리, 장애물 수가 수명에 영향을 줍니다. 배터리 잔량은 iMonnit에서 백분율로 확인할 수 있고, 설정 임계값 이하가 되면 알림을 받을 수 있습니다.':
      'It varies by environment, but a single AA battery can last up to 10+ years. Heartbeat interval, range and obstacles affect lifespan. Battery level is shown as a percentage in iMonnit, and you can receive an alert when it drops below a set threshold.',
    '사용자가 설정한 조건을 초과하면 iMonnit이 SMS 문자, 이메일, 전화로 즉시 알림을 보냅니다. 임계값과 수신자는 자유롭게 설정할 수 있습니다.':
      'When user-defined conditions are exceeded, iMonnit sends instant alerts by SMS, email or phone. Thresholds and recipients are fully configurable.',
    'Encrypt-RF® 기술로 256-bit ECDH 키 교환과 AES-128 암호화를 적용해 센서~게이트웨이 구간을 보안 터널로 보호합니다. 또한 패킷 변조 검증 루틴으로 위·변조 및 재전송 공격을 차단합니다.':
      'Encrypt-RF® applies 256-bit ECDH key exchange and AES-128 encryption to protect the sensor-to-gateway link as a secure tunnel. Packet-integrity verification also blocks tampering and replay attacks.',
    '아닙니다. 게이트웨이 연결이 끊겨도 센서가 자체적으로 최대 4,000건의 측정값을 저장하며, 연결이 복구되면 누락 없이 전송합니다. 게이트웨이 역시 내부 메모리에 다수의 메시지를 저장합니다.':
      'No. Even if the gateway connection drops, each sensor stores up to 4,000 readings locally and transmits them without loss once the connection is restored. The gateway also stores many messages in internal memory.',
    'ALTA 무선 센서는 비가시선 기준 벽 12장을 관통해 1,200ft 이상, ALTA XL 게이트웨이 사용 시 벽 18장 관통 2,000ft 이상까지 통신합니다. 안테나 방향과 설치 환경에 따라 최적 성능이 달라집니다.':
      'ALTA wireless sensors communicate over 1,200 ft through up to 12 walls (non-line-of-sight), and over 2,000 ft through 18 walls with an ALTA XL gateway. Optimal performance depends on antenna orientation and installation environment.',

