 "리테일 · 매장 · 외식 온도 관리": "Retail · Store · Food Service Temperature Control",
 "모든 항목은 필수입니다. 담당 엔지니어가 확인 후 필요한 자료를 추가로 안내드립니다.": "All fields are required. An assigned engineer will review your request and follow up with any additional materials needed.",
 "산업 · 제조": "Industrial · Manufacturing",
 "시설 · 안전": "Facilities · Safety",
 "온도 · 환경": "Temperature · Environment",
 "콜드체인 · 유통": "Cold Chain · Distribution",
 "랙 단위 열편차와 과냉각을 실측해, 더 차갑게가 아니라 정확하게 냉방하는 방법.": "Measuring rack-level thermal variance and overcooling to cool precisely, not simply colder.",
 "모터·펌프·감속기의 진동과 전류로 고장을 7~30일 전에 잡아내는 예지보전 설계.": "Predictive maintenance design that detects failures 7–30 days in advance from motor, pump and gearbox vibration and current.",
 "배관 피로, 구조 부재 변형, 회전설비 진동을 24bit 정밀도로 무선 계측합니다.": "Wireless measurement of pipe fatigue, structural member deformation and rotating equipment vibration with 24-bit precision.",
 "전원도 통신도 없는 초기 현장부터 사면·흙막이·양생 구간을 24시간 계측합니다.": "24/7 monitoring of slopes, earth retaining structures and concrete curing zones, even at early-stage sites without power or connectivity.",
 "배터리 열화와 수배전반 과열을 활선 상태에서 비접촉으로 감시합니다.": "Non-contact monitoring of battery degradation and switchgear overheating while systems remain energized.",
 "기존 수신반은 그대로 두고 경보만 담당자 휴대폰으로 직접 전달합니다.": "Keep your existing fire alarm control panel and deliver alarms directly to personnel's mobile phones.",
