 "Monnit Korea — 산업용 무선 IoT 센서·통합관제·AI 예지보전": "Monnit Korea — Industrial Wireless IoT Sensors, Integrated Monitoring & AI Predictive Maintenance",
 "현장에서 자주 발생하는 문제예요. 하나를 선택하세요.": "These are common on-site challenges. Please select one.",
 "Factory & manufacturing · 실시간 화재·과열 감시": "Factory & manufacturing · Real-Time Fire & Overheat Monitoring",
 "열·연기·과열을 무선 연동해 0.1초 내 경보를 전파합니다. 무인 시간대에도 담당자 휴대폰·SMS·전화로 즉시 통보됩니다. 특히 모터·펌프·공조기·전력 설비에 맞춰 센서를 구성합니다.": "Wirelessly interlinked heat, smoke and overheat detection propagates alarms within 0.1 seconds. Even during unattended hours, personnel are notified immediately by mobile app, SMS and phone call. Sensor configurations are tailored specifically to motors, pumps, air handling units and power equipment.",
 "온도 · 연기 연동 · 경보 릴레이 · 진동": "Temperature · Smoke Interlock · Alarm Relay · Vibration",
 "0.1초 경보 전파": "0.1 s Alarm Propagation",
 "대형 · 다지점·캠퍼스 — 게이트웨이 2대 이상 · 센서 50개+ · 통합관제": "Large · Multi-Site/Campus — 2+ Gateways · 50+ Sensors · Integrated Monitoring",
 "활용분야 상세 보기": "View Application Details",
 "Factory & manufacturing · 무선 누수·침수·동파 감지": "Factory & manufacturing · Wireless Leak, Flood & Freeze Detection",
 "로프·스팟 센서로 서버룸·기계실·배관·저수조의 누수·침수·동파 위험을 실시간 감시하고, 피해 확산 전에 알립니다. 특히 모터·펌프·공조기·전력 설비에 맞춰 센서를 구성합니다.": "Rope and spot sensors monitor server rooms, mechanical rooms, piping and water tanks in real time for leak, flood and freeze risks, issuing alerts before damage spreads. Sensor configurations are tailored specifically to motors, pumps, air handling units and power equipment.",
 "누수 로프 · 스팟 감지 · 온도 · 진동": "Leak Rope · Spot Detection · Temperature · Vibration",
 "-75% 누수 대응 시간": "-75% Leak Response Time",
 "Factory & manufacturing · 온·습도 실시간 모니터링": "Factory & manufacturing · Real-Time Temperature & Humidity Monitoring",
 "보관·생산·재실 공간의 온도와 습도를 24시간 감시하고, 설정 범위를 벗어나면 즉시 경보합니다. 특히 모터·펌프·공조기·전력 설비에 맞춰 센서를 구성합니다.": "Temperature and humidity in storage, production and occupied spaces are monitored 24/7, with immediate alarms whenever readings leave the set range. Sensor configurations are tailored specifically to motors, pumps, air handling units and power equipment.",
 "온도 · 습도 · 진동": "Temperature · Humidity · Vibration",
 "설정 이탈 즉시 경보": "Instant Out-of-Range Alarms",
 "Factory & manufacturing · 진동·전류 AI 예지보전": "Factory & manufacturing · AI Predictive Maintenance (Vibration & Current)",
 "모터·펌프·공조 설비의 진동과 전류 파형을 AI가 학습해 고장 징후를 2~4주 전에 경보합니다. 특히 모터·펌프·공조기·전력 설비에 맞춰 센서를 구성합니다.": "AI learns the vibration and current waveforms of motors, pumps and HVAC equipment to flag signs of failure 2–4 weeks in advance. Sensor configurations are tailored specifically to motors, pumps, air handling units and power equipment.",
 "진동 · 전류 · 온도": "Vibration · Current · Temperature",
 "-40% 비계획 정지": "-40% Unplanned Downtime",
 "Factory & manufacturing · 전력·에너지 모니터링": "Factory & manufacturing · Power & Energy Monitoring",
 "설비별 전력 사용과 가동 패턴을 계측해 낭비 구간을 특정하고 최적 운전을 제안합니다. 특히 모터·펌프·공조기·전력 설비에 맞춰 센서를 구성합니다.": "Power consumption and operating patterns are measured for each asset to pinpoint waste and recommend optimal operation. Sensor configurations are tailored specifically to motors, pumps, air handling units and power equipment.",
