 "-15% 에너지 사용량": "-15% Energy Use",
 "Logistics & cold chain · 실시간 화재·과열 감시": "Logistics & cold chain · Real-Time Fire & Overheat Monitoring",
 "열·연기·과열을 무선 연동해 0.1초 내 경보를 전파합니다. 무인 시간대에도 담당자 휴대폰·SMS·전화로 즉시 통보됩니다. 특히 냉동·냉장 창고·수송 차량에 맞춰 센서를 구성합니다.": "Wirelessly interlinked heat, smoke and overheat detection propagates alarms within 0.1 seconds. Even during unattended hours, personnel are notified immediately by mobile app, SMS and phone call. Sensor configurations are tailored specifically to freezer and cold storage warehouses and transport vehicles.",
 "온도 · 연기 연동 · 경보 릴레이 · 저온": "Temperature · Smoke Interlock · Alarm Relay · Low Temperature",
 "Logistics & cold chain · 온·습도 실시간 모니터링": "Logistics & cold chain · Real-Time Temperature & Humidity Monitoring",
 "보관·생산·재실 공간의 온도와 습도를 24시간 감시하고, 설정 범위를 벗어나면 즉시 경보합니다. 특히 냉동·냉장 창고·수송 차량에 맞춰 센서를 구성합니다.": "Temperature and humidity in storage, production and occupied spaces are monitored 24/7, with immediate alarms whenever readings leave the set range. Sensor configurations are tailored specifically to freezer and cold storage warehouses and transport vehicles.",
 "온도 · 습도 · 저온": "Temperature · Humidity · Low Temperature",
 "Logistics & cold chain · 냉장·콜드체인 실시간 감시": "Logistics & cold chain · Real-Time Refrigeration & Cold Chain Monitoring",
 "냉장·냉동 설비와 콜드체인 구간의 온·습도를 24시간 감시하고, 규정 이탈 시 즉시 경보합니다. 자동 기록으로 HACCP·GMP 증빙까지 간편합니다. 특히 냉동·냉장 창고·수송 차량에 맞춰 센서를 구성합니다.": "Temperature and humidity across refrigeration and freezer equipment and cold chain segments are monitored 24/7, with immediate alarms on any compliance deviation. Automatic logging also simplifies HACCP and GMP documentation. Sensor configurations are tailored specifically to freezer and cold storage warehouses and transport vehicles.",
 "저온 · 온습도 · 도어": "Low Temperature · Temp/Humidity · Door",
 "온도 이탈 즉시 경보": "Instant Temperature Excursion Alarms",
 "Logistics & cold chain · 다현장 통합 관제 플랫폼": "Logistics & cold chain · Multi-Site Integrated Monitoring Platform",
