 "멀티 센서 · 게이트웨이 · 저온": "Multi-Sensor · Gateway · Low Temperature",
 "단일 플랫폼 통합": "Single-Platform Integration",
 "Logistics & cold chain · 규정·온도기록 자동화": "Logistics & cold chain · Compliance & Temperature Logging Automation",
