 "여러 설비와 현장을 단일 대시보드로 통합 가시화하고, 이상은 우선순위로 원격 알림합니다. 특히 서버 랙·HVAC·전력·누수 구간에 맞춰 센서를 구성합니다.": "Multiple assets and sites are unified on a single dashboard, with anomalies delivered as prioritized remote alerts. Sensor configurations are tailored specifically to server racks, HVAC, power systems and leak-prone zones.",
 "멀티 센서 · 게이트웨이 · 차압": "Multi-Sensor · Gateway · Differential Pressure",
 "Office & commercial buildings · 실시간 화재·과열 감시": "Office & commercial buildings · Real-Time Fire & Overheat Monitoring",
 "열·연기·과열을 무선 연동해 0.1초 내 경보를 전파합니다. 무인 시간대에도 담당자 휴대폰·SMS·전화로 즉시 통보됩니다. 특히 오피스·매장·기계실·전기실·주차장에 맞춰 센서를 구성합니다.": "Wirelessly interlinked heat, smoke and overheat detection propagates alarms within 0.1 seconds. Even during unattended hours, personnel are notified immediately by mobile app, SMS and phone call. Sensor configurations are tailored specifically to offices, retail spaces, mechanical rooms, electrical rooms and parking garages.",
 "온도 · 연기 연동 · 경보 릴레이 · 전류": "Temperature · Smoke Interlock · Alarm Relay · Current",
 "Office & commercial buildings · 무선 누수·침수·동파 감지": "Office & commercial buildings · Wireless Leak, Flood & Freeze Detection",
 "로프·스팟 센서로 서버룸·기계실·배관·저수조의 누수·침수·동파 위험을 실시간 감시하고, 피해 확산 전에 알립니다. 특히 오피스·매장·기계실·전기실·주차장에 맞춰 센서를 구성합니다.": "Rope and spot sensors monitor server rooms, mechanical rooms, piping and water tanks in real time for leak, flood and freeze risks, issuing alerts before damage spreads. Sensor configurations are tailored specifically to offices, retail spaces, mechanical rooms, electrical rooms and parking garages.",
 "누수 로프 · 스팟 감지 · 온도 · 전류": "Leak Rope · Spot Detection · Temperature · Current",
 "Office & commercial buildings · 온·습도 실시간 모니터링": "Office & commercial buildings · Real-Time Temperature & Humidity Monitoring",
 "보관·생산·재실 공간의 온도와 습도를 24시간 감시하고, 설정 범위를 벗어나면 즉시 경보합니다. 특히 오피스·매장·기계실·전기실·주차장에 맞춰 센서를 구성합니다.": "Temperature and humidity in storage, production and occupied spaces are monitored 24/7, with immediate alarms whenever readings leave the set range. Sensor configurations are tailored specifically to offices, retail spaces, mechanical rooms, electrical rooms and parking garages.",
